    csil_m["scores"] = v.scores
    csil_m["enabled"] = v.enabled
    csil_m["endpoint"] = _encode_endpoint_value(v.endpoint)
    csil_m["attributes"] = v.attributes
    csil_m["updated_ms"] = v.updated_ms
