    tree = _csil_expect_map(tree)
    return Model(
        name=_csil_expect_text(tree["name"]),
        description=_csil_expect_text(tree["description"]),
        endpoint=_decode_endpoint_value(tree["endpoint"]),
        tags=[_csil_expect_text(csil_e) for csil_e in _csil_expect_array(tree["tags"])],
        attributes={_csil_expect_text(csil_k): _csil_expect_text(csil_v) for csil_k, csil_v in _csil_expect_map(tree["attributes"]).items()},
        cost=_decode_cost_value(tree["cost"]),
        scores={_csil_expect_text(csil_k): _csil_expect_float(csil_v) for csil_k, csil_v in _csil_expect_map(tree["scores"]).items()},
        calibration={_csil_expect_text(csil_k): _csil_expect_float(csil_v) for csil_k, csil_v in _csil_expect_map(tree["calibration"]).items()},
        enabled=_csil_expect_bool(tree["enabled"]),
        updated_ms=_csil_expect_uint(tree["updated_ms"]),
    )


